def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    D = 10
    N = int(budget / (dim * D))
    P = 20  # Population size
    sigma = 0.1

    x = rng.uniform(lb, ub, size=(P, dim))

    for i in range(N):
        F = rng.uniform(0.5, 1.5)
        X = np.copy(x)

        for p in range(P):
            a = rng.choice(P, size=D, replace=False)
            b = rng.choice(D, size=P, replace=True)

            trial = clip(X[a[b]] + F * (x[p] - X[a[b]]))
            trial += rng.normal(0, sigma, size=dim)
            x[p] = np.where(np.random.rand(dim) < 0.5, trial, x[p])

        f = func(x)

    idx = np.argmin(f)
    return clip(x[idx])

def algorithm(func, dim, lb, ub, budget, rng):
    def generate_initial_population(dim, lb, ub, rng):
        return np.clip(rng.uniform(lb, ub, size=(dim, 10)), a_min=lb, a_max=ub)

    population = generate_initial_population(dim, lb, ub, rng)
    best = func(population[0])

    for _ in range(budget - 1):
        mutant = population + rng.normal(size=(dim, 10)) * 0.5
        mutant = np.clip(mutant, a_min=lb, a_max=ub)

        crossover = (mutant + population) / 2

        candidate = func(np.array(crossover))
        if candidate < best:
            best = candidate
            population[0] = crossover

    return population[0]

